text:
.outreach-lower {
  --bg: var(--color-lower-sections-bg-1);
  --bg2: var(--color-lower-sections-bg2-2);
  --card: var(--landing-card);
  --line: var(--color-lower-sections-line-4);
  --line2: var(--color-lower-sections-line2-5);
  --tx: var(--landing-fg);
  --mu: var(--landing-muted);
  --pu: var(--color-lower-sections-pu-8);
  --pk: var(--color-lower-sections-pk-9);
  --gr: var(--color-lower-sections-gr-10);
  --ye: var(--color-lower-sections-ye-11);
  --grad: linear-gradient(
    135deg,
    var(--color-lower-sections-grad-12),
    var(--color-lower-sections-pk-9)
  );
}
[data-theme="light"] .outreach-lower {
  --bg: var(--color-lower-sections-bg-13);
  --bg2: var(--color-lower-sections-bg2-14);
  --card: var(--landing-card);
  --line: var(--color-lower-sections-line-16);
  --line2: var(--color-lower-sections-line2-17);
  --tx: var(--landing-fg);
  --mu: var(--landing-muted);
  --pu: var(--color-lower-sections-pu-20);
  --pk: var(--color-lower-sections-pk-21);
  --gr: var(--color-lower-sections-gr-22);
  --ye: var(--color-lower-sections-ye-23);
  --grad: linear-gradient(
    135deg,
    var(--color-lower-sections-grad-12),
    var(--color-lower-sections-pk-9)
  );
  --text-grad: linear-gradient(
    135deg,
    var(--color-lower-sections-text-grad-24),
    var(--color-lower-sections-text-grad-25)
  );
}
.outreach-lower h2,
.outreach-lower h3 {
  font-family: inherit;
}
.lower-g {
  -webkit-background-clip: text;
}
/* steps */
.lower-steps::before {
  content: "";
  position: absolute;
  left: 8%;
  right: 8%;
  top: 27px;
  height: 2px;
  background: linear-gradient(90deg, var(--pu), var(--pk));
  opacity: 0.35;
}
[data-theme="light"] .lower-vis {
  background: var(--color-lower-sections-background-28);
}
.lower-chk.lower-on {
  background: var(--grad);
  border-color: transparent;
}
.lower-btn {
  --button-hover-filter: none;
}
.lower-btn:focus-visible,
.outreach-lower a:focus-visible {
  outline: 2px solid var(--pk);
  outline-offset: 3px;
}
/* bento */
.lower-env span::before {
  content: "✉";
  display: block;
  font-size: 18px;
  color: var(--pk);
}
[data-theme="light"] .lower-gm {
  background: var(--color-lower-sections-background-28);
}
/* cta */
[data-theme="light"] .lower-plan {
  background: var(--color-lower-sections-background-39);
}
.lower-plan li::before {
  content: "✓";
  color: var(--gr);
  font-weight: 800;
  margin-right: 10px;
}
@media (max-width: 860px) {
  .lower-steps::before {
    display: none;
  }
}
/* Offset the hero container’s gutters so these sections keep their own 24px. */
.landing-container > .lower-wrap {
  width: min(1120px, 100vw);
  position: relative;
  left: 50%;
  transform: translateX(-50%);
}

@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .outreach-lower
    :is(
      .lower-panel,
      .lower-plan,
      .lower-vis,
      .lower-pdf,
      .lower-gm,
      .lower-env > span
    ) {
    transition:
      translate 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
      border-color 220ms ease;
  }

  .outreach-lower :is(.lower-panel, .lower-plan):hover {
    translate: 0 -5px;
  }

  .outreach-lower
    :is(.lower-vis, .lower-pdf, .lower-gm, .lower-env > span):hover {
    translate: 0 -3px;
  }
}

@media (hover: hover) {
  .lower-step :is(.lower-panel, .lower-vis):hover {
    border-color: var(--line2);
  }
}

.lower-plan li[data-unavailable]::before {
  content: "−";
  color: var(--mu);
}
